package dev.eugheist.tc4modern;
import java.util.*;
import net.minecraft.core.*;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.*;
import net.minecraft.world.entity.*;
import net.minecraft.world.entity.item.ItemEntity;
import net.minecraft.world.item.*;
import net.minecraft.world.item.context.UseOnContext;
import net.minecraft.world.level.block.*;
import net.minecraft.world.phys.*;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
import thaumcraft.api.aspects.*;
@EventBusSubscriber(modid=TC4Modern.MODID,value=net.neoforged.api.distmarker.Dist.CLIENT)
final class ElementalToolsAudit {
 static int ticks;static volatile int stage;static final BlockPos POS=InfusionAudit.POS;static ElementalTools.FollowingItem following;
 static void check(boolean b,String s){if(!b)throw new IllegalStateException("TC4_ELEMENTAL FAIL "+s);System.out.println("TC4_ELEMENTAL PASS "+s);}
 static InfusionItemRecipes.Recipe recipe(String key){return InfusionItemRecipes.all().stream().filter(r->r.key().equals(key)).findFirst().orElseThrow();}
 static void start(ServerPlayer p,String key){InfusionAudit.matrix.logic.crafting=false;var l=p.serverLevel();var r=recipe(key);var center=(InfusionContent.PedestalEntity)l.getBlockEntity(POS.below(2));center.setItem(new ItemStack(r.central().get()));for(var pos:TravellerBootsAudit.PEDESTALS)l.setBlock(pos,Blocks.AIR.defaultBlockState(),3);var parts=r.componentStacks();for(int i=0;i<parts.size();i++){var pos=TravellerBootsAudit.PEDESTALS.get(i);l.setBlock(pos,InfusionContent.PEDESTAL.get().defaultBlockState(),3);((InfusionContent.PedestalEntity)l.getBlockEntity(pos)).setItem(parts.get(i));}for(int x=-8;x<=8;x++)l.setBlock(POS.offset(x,-2,-4),Blocks.AIR.defaultBlockState(),3);int i=0;for(var a:r.aspects().getAspects()){var pos=POS.offset(i++*3-3,-2,-4);l.setBlock(pos,EssentiaDevices.JAR.get().defaultBlockState(),3);var jar=(WardedJarEntity)l.getBlockEntity(pos);jar.state.aspect=a;jar.state.amount=r.aspects().getAmount(a);jar.changed();}l.getEntitiesOfClass(ItemEntity.class,new AABB(POS).inflate(30)).forEach(Entity::discard);InfusionAudit.click(p,p.getInventory().items.stream().filter(WandData::isWand).findFirst().orElseThrow());check(InfusionAudit.matrix.logic.crafting&&InfusionAudit.matrix.logic.recipeIngredients.size()==4&&InfusionAudit.matrix.logic.recipeEssentia.visSize()==24,"actual altar starts "+key+" four components24essentia");}
 static void finish(ServerPlayer p,String key){var r=recipe(key);var l=p.serverLevel();check(!InfusionAudit.matrix.logic.crafting&&((InfusionContent.PedestalEntity)l.getBlockEntity(POS.below(2))).item().is(r.output().get()),"natural altar crafts "+key);for(int i=0;i<4;i++)check(((InfusionContent.PedestalEntity)l.getBlockEntity(TravellerBootsAudit.PEDESTALS.get(i))).item().isEmpty(),"actual component consumed "+key+"/"+i);for(int i=0;i<r.aspects().size();i++)check(((WardedJarEntity)l.getBlockEntity(POS.offset(i*3-3,-2,-4))).state.amount==0,"exact essentia consumed "+key+"/"+i);}
 static void prepare(ServerPlayer p){p.getInventory().selected=0;InfusionAudit.prepare(p);var l=p.serverLevel();l.setDayTime(6000);l.setWeatherParameters(10000,0,false,false);var axe=new ItemStack(ElementalTools.item("axe"));var pick=new ItemStack(ElementalTools.item("pickaxe"));for(var s:List.of(axe,pick))check(s.getMaxDamage()==1500&&s.getEnchantmentValue()==18&&s.getItem().isValidRepairItem(s,new ItemStack(TC4Modern.THAUMIUM.get()))&&s.is(net.minecraft.tags.TagKey.create(net.minecraft.core.registries.Registries.ITEM,AlchemyContent.id("repairable"))),"original1500durability18ench thaumiumrepair+Repairtag "+s.getItem());
  var root=POS.offset(-7,-2,5);for(int i=0;i<6;i++)l.setBlock(root.above(i),Blocks.OAK_LOG.defaultBlockState(),3);l.setBlock(root.above(7),Blocks.BIRCH_LOG.defaultBlockState(),3);p.setItemInHand(InteractionHand.MAIN_HAND,axe);p.setShiftKeyDown(false);check(ElementalTools.furthest(l,root,Blocks.OAK_LOG).equals(root.above(5)),"original greedy same-log furthest acrosstwo-block-neighbours");p.gameMode.destroyBlock(root);check(l.getBlockState(root).is(Blocks.OAK_LOG)&&l.isEmptyBlock(root.above(5))&&l.getBlockState(root.above(4)).is(Blocks.OAK_LOG)&&l.getBlockState(root.above(7)).is(Blocks.BIRCH_LOG)&&axe.getDamageValue()==1,"actual gameMode break intercept removes only furthest same-log +1durability");following=l.getEntitiesOfClass(ElementalTools.FollowingItem.class,new AABB(root).inflate(10)).stream().findFirst().orElseThrow();check(following.target()==p&&following.getItem().is(Items.OAK_LOG),"actual harvest drops become homing originalitemstack");p.setShiftKeyDown(true);p.gameMode.destroyBlock(root);check(l.isEmptyBlock(root)&&l.getBlockState(root.above()).is(Blocks.OAK_LOG),"sneaking uses ordinary axe harvest");p.setShiftKeyDown(false);
  var item=new ItemEntity(l,p.getX()+9,p.getY()+9,p.getZ()+9,new ItemStack(Items.DIAMOND));l.addFreshEntity(item);item.setDeltaMovement(-2,-2,-2);axe.getItem().onUseTick(l,p,axe,71999);var v=item.getDeltaMovement();check(Math.abs(v.x+.35)<.00001&&Math.abs(v.y+.35)<.00001&&Math.abs(v.z+.35)<.00001,"axe attraction original10cube including farcorner caps EACHaxis .35");check(axe.getDamageValue()==2,"attraction costs no durability after ordinaryharvest");item.discard();
  p.setItemInHand(InteractionHand.MAIN_HAND,pick);pick.enchant(p.registryAccess().lookupOrThrow(net.minecraft.core.registries.Registries.ENCHANTMENT).getOrThrow(net.minecraft.world.item.enchantment.Enchantments.FORTUNE),20);var ore=POS.offset(8,-2,6);l.setBlock(ore,Blocks.IRON_ORE.defaultBlockState(),3);p.gameMode.destroyBlock(ore);check(l.getEntitiesOfClass(ItemEntity.class,new AABB(ore).inflate(2)).stream().anyMatch(i->i.getItem().is(net.minecraft.core.registries.BuiltInRegistries.ITEM.get(AlchemyContent.id("iron_cluster")))),"actual ore harvest creates nativecluster with fortune chance");pick.setDamageValue(0);var victim=EntityType.HUSK.create(l);victim.moveTo(p.position());((ElementalTools.Pick)pick.getItem()).onLeftClickEntity(pick,p,victim);check(victim.getRemainingFireTicks()==40,"pick melee ignites2seconds");var c=new UseOnContext(p,InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(root),Direction.UP,root,false));check(pick.getItem().useOn(c)==InteractionResult.PASS&&pick.getDamageValue()==5,"pick scan retains originalPASS and5durability");
  l.setBlock(POS.offset(0,-1,5),Blocks.DIAMOND_ORE.defaultBlockState(),3);l.setBlock(POS.offset(-2,-1,5),Blocks.WATER.defaultBlockState(),3);l.setBlock(POS.offset(2,-1,5),Blocks.LAVA.defaultBlockState(),3);for(int x=-3;x<=3;x++)for(int y=-2;y<=1;y++)l.setBlock(POS.offset(x,y,3),Blocks.STONE.defaultBlockState(),3);
  start(p,"ElementalAxe");p.getAbilities().mayfly=true;p.getAbilities().flying=true;p.onUpdateAbilities();p.connection.teleport(POS.getX()+4,POS.getY()+1,POS.getZ()-4,15,15);stage=1;
 }
 @SubscribeEvent static void tick(net.neoforged.neoforge.client.event.ClientTickEvent.Post e){if(!Boolean.getBoolean("tc4modern.elementalAuditOnly"))return;var mc=net.minecraft.client.Minecraft.getInstance();if(mc.player==null||mc.level==null)return;ticks++;var s=mc.getSingleplayerServer();var id=mc.player.getUUID();if(ticks==80)s.execute(()->prepare(s.getPlayerList().getPlayer(id)));if(ticks==150){check(stage==1,"server mechanics passed");mc.player.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(ElementalTools.item("pickaxe")));var at=POS.offset(0,-1,5);var ctx=new UseOnContext(mc.player,InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(at),Direction.UP,at,false));mc.player.getMainHandItem().getItem().useOn(ctx);check(ElementalToolsClient.scanned.get(at)==7&&ElementalToolsClient.scanned.get(at.offset(-2,0,0))==-5&&ElementalToolsClient.scanned.get(at.offset(2,0,0))==-10,"actual client use scans ore water lava behindstone");}if(ticks==170){check(!ElementalToolsClient.scanned.containsKey(POS.offset(0,-1,3)),"ore-replaceable stone is NOT an ore");check(ElementalToolsClient.rendered>0,"native throughwall scan quads rendered");LiquidDeathAudit.shot(mc,"elemental-pick-scan.png");}if(ticks==180&&Boolean.getBoolean("tc4modern.elementalQuickAuditOnly")){mc.stop();return;}if(ticks==850)s.execute(()->{var p=s.getPlayerList().getPlayer(id);finish(p,"ElementalAxe");start(p,"ElementalPick");stage=2;});if(ticks==1600)s.execute(()->{finish(s.getPlayerList().getPlayer(id),"ElementalPick");stage=3;});if(ticks>=1620&&(ticks-1620)%20==0){check(stage==3,"both natural infusions completed");int i=(ticks-1620)/20;if(i>=4){mc.stop();return;}var inv=mc.player.getInventory();var book=new ThaumonomiconScreen(new ThaumonomiconMenu(0,inv),inv,net.minecraft.network.chat.Component.empty());book.auditOpen(thaumcraft.api.research.ResearchCategories.getResearch(i<2?"ELEMENTALAXE":"ELEMENTALPICK"),i%2==0?0:2);mc.setScreen(book);}if(ticks>=1625&&(ticks-1625)%20==0)LiquidDeathAudit.shot(mc,"elemental-tools-book-"+(ticks-1625)/20+".png");}
}
